static Map<Thread, StackTraceElement[]> filterByNamePrefix(String prefix) {
    Map<Thread, StackTraceElement[]> wynik = new LinkedHashMap<>();
    for (Map.Entry<Thread, StackTraceElement[]> e : Thread.getAllStackTraces().entrySet()) if (e.getKey().getName().startsWith(prefix)) wynik.put(e.getKey(), e.getValue());
