class ThreadDiagnostics {
    static String snapshot() {
        StringBuilder sb = new StringBuilder();
        for (Thread t : Thread.getAllStackTraces().keySet()) sb.append(t.getName()).append(";");
        return sb.toString();
    }
    static void compareSnapshots(String before, String after) {
        Set<String> beforeSet = new HashSet<>(Arrays.asList(before.split(";")));
        Set<String> afterSet = new HashSet<>(Arrays.asList(after.split(";")));
        Set<String> zniknely = new HashSet<>(beforeSet); zniknely.removeAll(afterSet);
        Set<String> pojawily = new HashSet<>(afterSet); pojawily.removeAll(beforeSet);
        System.out.println("zniknely: "+zniknely+" pojawily: "+pojawily);
    }
}
