class ProductionDumpSimulator {
    static Path generateDump(Path katalog) throws IOException {
        StringBuilder sb = new StringBuilder();
        sb.append("Thread Dump wygenerowany: ").append(java.time.Instant.now()).append("\n\n");
        for (Map.Entry<Thread, StackTraceElement[]> e : Thread.getAllStackTraces().entrySet()) {
            sb.append("\"").append(e.getKey().getName()).append("\" state=").append(e.getKey().getState()).append("\n");
            for (StackTraceElement el : e.getValue()) sb.append("    at ").append(el).append("\n");
            sb.append("\n");
        }
        Path plik = katalog.resolve("thread-dump-"+System.currentTimeMillis()+".txt");
        Files.writeString(plik, sb.toString());
        return plik;
    }
}
