static String diagnoseThreadIssue(long observeMs) throws InterruptedException {
    long[] deadlocked = ManagementFactory.getThreadMXBean().findDeadlockedThreads();
    if (deadlocked != null) return "DEADLOCK";
    Map<Thread, Thread.State> przed = new HashMap<>();
    for (Thread t : Thread.getAllStackTraces().keySet()) przed.put(t, t.getState());
    Thread.sleep(observeMs);
    boolean wszystkieRunnable = true;
    for (Map.Entry<Thread, Thread.State> e : przed.entrySet()) if (e.getKey().isAlive() && e.getKey().getState() != Thread.State.RUNNABLE) wszystkieRunnable = false;
    return wszystkieRunnable ? "PODEJRZENIE LIVELOCK" : "OK";
}
