static int findPeakThreadCount(long observeMs, long sampleIntervalMs) throws InterruptedException {
    int max = 0;
    long koniec = System.currentTimeMillis()+observeMs;
    while (System.currentTimeMillis() < koniec) { max = Math.max(max, Thread.getAllStackTraces().size()); Thread.sleep(sampleIntervalMs); }
    return max;
}
