static void detectThreadLeak(int baseline, int checkIntervalMs, int checks) throws InterruptedException {
    int poprzedni = baseline;
    int rosnacychPodRzad = 0;
    for (int i=0;i<checks;i++) {
        Thread.sleep(checkIntervalMs);
        int aktualny = Thread.getAllStackTraces().size();
        if (aktualny > poprzedni) rosnacychPodRzad++; else rosnacychPodRzad=0;
        if (rosnacychPodRzad >= 3) System.out.println("OSTRZEZENIE: mozliwy wyciek watkow ("+aktualny+" aktywnych)");
        poprzedni = aktualny;
    }
}
