class PostMortemReport {
    static void generate() {
        Map<Thread, StackTraceElement[]> dump = Thread.getAllStackTraces();
        System.out.println("=== RAPORT POST-MORTEM ===");
        System.out.println("Liczba watkow: "+dump.size());
        long deamony = dump.keySet().stream().filter(Thread::isDaemon).count();
        System.out.println("Watki demoniczne: "+deamony+", uzytkownika: "+(dump.size()-deamony));
        Map<Thread.State, Long> wgStanu = dump.keySet().stream().collect(Collectors.groupingBy(Thread::getState, Collectors.counting()));
        System.out.println("Wg stanu: "+wgStanu);
        long[] deadlocked = ManagementFactory.getThreadMXBean().findDeadlockedThreads();
        System.out.println("Deadlock: "+(deadlocked != null ? "WYKRYTY ("+deadlocked.length+" watkow)" : "brak"));
    }
}
