static void runDiagnosticCenter(boolean symulujDeadlock) throws Exception {
    if (symulujDeadlock) {
        Object lockA = new Object(), lockB = new Object();
        Thread t1 = new Thread(() -> { synchronized (lockA) { try { Thread.sleep(300); } catch (Exception e) {} synchronized (lockB) {} } });
        Thread t2 = new Thread(() -> { synchronized (lockB) { try { Thread.sleep(300); } catch (Exception e) {} synchronized (lockA) {} } });
        t1.setDaemon(true); t2.setDaemon(true);
        t1.start(); t2.start();
    }
    Thread.sleep(400);
    long[] deadlocked = ManagementFactory.getThreadMXBean().findDeadlockedThreads();
    if (deadlocked != null) {
        Path plik = Files.createTempFile("raport-diagnostyczny", ".txt");
        Files.writeString(plik, "WYKRYTO DEADLOCK: "+deadlocked.length+" watkow\n");
        System.out.println("raport zapisany: "+plik);
    } else {
        System.out.println("brak problemow - raport NIE wygenerowany");
    }
}
runDiagnosticCenter(false);
runDiagnosticCenter(true);
